pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        PayableTarget t = new PayableTarget();

        vm.deal(address(this), 1 ether);
        vm.deal(address(t), 1 ether);

        uint256 beforeCount = c.depositsCount();

        c.sendMoney(address(t), amount);

        uint256 afterCount = c.depositsCount();

        assertTrue(afterCount == beforeCount);
    }
}

contract PayableTarget {
    receive() external payable {}
}
